package vn.hust.restaurant.service;import java.math.*;import java.sql.*;import java.time.*;import java.util.*;import vn.hust.restaurant.model.Ingredient;import vn.hust.restaurant.repository.InventoryRepository;public class InventoryService{private final InventoryRepository r;public InventoryService(InventoryRepository r){this.r=r;}public List<Ingredient>list(String k)throws SQLException{return r.ingredients(k);}public Map<Integer,String>categories()throws SQLException{return r.categories();}public void save(Ingredient x)throws SQLException{if(x.name().isBlank()||x.stock().signum()<0||x.minimumStock().signum()<0)throw new IllegalArgumentException("Dữ liệu nguyên liệu không hợp lệ");r.saveIngredient(x);}public List<InventoryRepository.Supplier>suppliers()throws SQLException{return r.suppliers();}public void saveSupplier(InventoryRepository.Supplier x)throws SQLException{r.saveSupplier(x);}public long receive(int e,int s,int i,BigDecimal q,BigDecimal c,LocalDate d,String n)throws SQLException{if(q.signum()<=0||c.signum()<0)throw new IllegalArgumentException("Số lượng/giá nhập không hợp lệ");return r.receive(e,s,i,q,c,d,n);}public void adjust(int e,int i,BigDecimal q,String reason)throws SQLException{if(reason.isBlank())throw new IllegalArgumentException("Phải nhập lý do");r.adjust(e,i,q,reason);}public void recipe(int m,int i,BigDecimal a)throws SQLException{if(a.signum()<=0)throw new IllegalArgumentException("Định lượng phải > 0");r.saveRecipe(m,i,a);}}
